values
  ('b1000000-0000-4000-8000-000000000001', null, 'San Francisco-Marin Food Bank', 'The primary hunger-relief organization for San Francisco and Marin County, running three warehouses that distribute food across the region.', 'https://www.sfmfoodbank.org', 'https://www.google.com/s2/favicons?domain=www.sfmfoodbank.org&sz=128', 'food', array['good for crews'], false, false, 14, 'United States', 'CA', 'San Francisco', true, true, 'both', false),
  ('b1000000-0000-4000-8000-000000000002', null, 'Friends of SFACC', 'The nonprofit support organization for San Francisco Animal Care and Control, the city public animal shelter.', 'https://friendsofsfacc.org', 'https://www.google.com/s2/favicons?domain=friendsofsfacc.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 12, 'United States', 'CA', 'San Francisco', true, true, 'ongoing', false),
  ('b1000000-0000-4000-8000-000000000003', null, 'San Francisco Recreation and Parks', 'The city department managing parks across San Francisco, including Golden Gate Park, coordinating volunteer maintenance and restoration projects.', 'https://sfrecpark.org', 'https://www.google.com/s2/favicons?domain=sfrecpark.org&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'CA', 'San Francisco', true, true, 'both', false),
  ('b1000000-0000-4000-8000-000000000004', null, 'Golden Gate National Parks Conservancy', 'The nonprofit partner of the National Park Service caring for the Golden Gate National Recreation Area, one of the largest urban national parks in the world.', 'https://www.parksconservancy.org', 'https://www.google.com/s2/favicons?domain=www.parksconservancy.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'CA', 'San Francisco', true, true, 'both', false),
  ('b1000000-0000-4000-8000-000000000005', null, 'San Francisco Environment Department', 'The city department leading San Francisco environmental policy and programs across zero waste, biodiversity, clean energy, and sustainable living.', 'https://www.sfenvironment.org', 'https://www.google.com/s2/favicons?domain=www.sfenvironment.org&sz=128', 'environment', array['leadership role'], false, false, 0, 'United States', 'CA', 'San Francisco', true, true, 'both', false),
  ('b1000000-0000-4000-8000-000000000006', null, 'Saved By Nature', 'A Bay Area nonprofit connecting teens with the outdoors through hike leadership, community outreach, and environmental education roles.', 'https://www.savedbynature.org', 'https://www.google.com/s2/favicons?domain=www.savedbynature.org&sz=128', 'environment', array['leadership role', 'counts for school hours'], false, false, 14, 'United States', 'CA', 'San Francisco', true, true, 'ongoing', false),
  ('b1000000-0000-4000-8000-000000000007', null, 'UCSF Benioff Children''s Hospitals', 'A leading pediatric hospital system with campuses in San Francisco and Oakland, running teen-specific volunteer programs including Junior Ambassadors.', 'https://www.ucsfbenioffchildrens.org', 'https://www.google.com/s2/favicons?domain=www.ucsfbenioffchildrens.org&sz=128', 'medicine', array['counts for school hours'], false, false, 14, 'United States', 'CA', 'San Francisco', true, true, 'both', false),
  ('b1000000-0000-4000-8000-000000000008', null, 'Boys and Girls Clubs of San Francisco', 'A youth development organization running academic support, enrichment, and teen services programs across San Francisco clubhouses.', 'https://www.kidsclub.org', 'https://www.google.com/s2/favicons?domain=www.kidsclub.org&sz=128', 'community', array['recurring', 'leadership role'], false, false, 14, 'United States', 'CA', 'San Francisco', true, true, 'ongoing', false),
  ('b1000000-0000-4000-8000-000000000009', null, 'Mission Graduates', 'A San Francisco nonprofit supporting Mission District youth from early education through college with tutoring, mentorship, and community engagement.', 'https://www.missiongraduates.org', 'https://www.google.com/s2/favicons?domain=www.missiongraduates.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'CA', 'San Francisco', true, true, 'ongoing', false)
