insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('b2000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000001', 'Volunteer at the SF-Marin Food Bank', 'food', 'Warehouse volunteers repack dry goods, sort produce, fill food boxes for seniors, and pack bags for home-delivered groceries at any of three Bay Area locations. All three warehouses welcome teenage volunteers, making this one of the most accessible options in the city.', array['good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.sfmfoodbank.org/volunteer/', 'https://www.sfmfoodbank.org/volunteer/', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000002', 'Volunteer with San Francisco Animal Care and Control', 'animals', 'Volunteers walk dogs, socialize cats and small animals, help with laundry and toy sorting, and support outreach events. Volunteers under 18 need a parent or guardian to attend orientation with them and commit to at least two hours a week for six months.', array['family friendly', 'recurring'], 12, false, false, true, '2 hrs / week', 'https://friendsofsfacc.org/volunteer/', 'https://friendsofsfacc.org/volunteer/', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000003', 'Volunteer with San Francisco Recreation and Parks', 'environment', 'Volunteers help with weeding, planting, mulching, habitat restoration, trash pickup, painting, and trail work at parks across the city, including Golden Gate Park and Mission Dolores Park. It is one of the easiest ways to find an outdoor project close to home in San Francisco.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://sfrecpark.org/1665/Park-Volunteers', 'https://sfrecpark.org/1665/Park-Volunteers', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000004', 'Volunteer with the Golden Gate National Parks Conservancy', 'environment', 'Volunteers help protect beaches and native habitats by removing litter and debris and minimizing marine debris across the Golden Gate National Recreation Area. It is a strong pick if you want your service tied to a nationally significant park system.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://www.parksconservancy.org/volunteer/volunteer-projects-and-activities', 'https://www.parksconservancy.org/volunteer/volunteer-projects-and-activities', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000005', 'Volunteer with SF Environment', 'environment', 'Volunteers support city initiatives around zero waste, biodiversity, clean energy, and sustainable living, connecting with others working on the same issues. It is a good option if you are interested in environmental policy and systems, not just hands-on cleanup work.', array['leadership role'], 0, false, false, true, 'Varies', 'https://www.sfenvironment.org/volunteer', 'https://www.sfenvironment.org/volunteer', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000006', 'b1000000-0000-4000-8000-000000000006', 'Volunteer with Saved By Nature', 'environment', 'High schoolers can train to become hike leaders for SF parks, do community outreach connecting with SF neighborhoods, or support administrative work, all with mentorship from experienced outdoor educators. It is a great option if you want structured training and a real leadership role outdoors.', array['leadership role', 'counts for school hours'], 14, false, false, true, 'Flexible', 'https://www.savedbynature.org/get-involved/volunteer-opportunities-bay-area', 'https://www.savedbynature.org/get-involved/volunteer-opportunities-bay-area', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000007', 'Join UCSF Benioff Children''s Hospitals Junior Ambassadors', 'medicine', 'Junior Ambassadors ages 14-18 support patients and families by making bedside activity kits, crafting holiday cards, and collecting essential items for families in care, while the Summer Student Program (ages 16-18) offers a structured weekly hospital shift. It is a strong option no matter which age bracket you are in.', array['counts for school hours'], 14, false, false, true, 'Varies', 'https://www.ucsfbenioffchildrens.org/about/become-a-volunteer', 'https://www.ucsfbenioffchildrens.org/about/become-a-volunteer', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000008', 'b1000000-0000-4000-8000-000000000008', 'Volunteer with Boys and Girls Clubs of San Francisco', 'community', 'Volunteers support Power Hour homework help, tutoring, STEM enrichment, and teen services like college prep and career readiness, as well as sports, fitness, and art programs. It is a great option if you want variety across academics, wellness, and creative activities.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://www.kidsclub.org/get-involved/volunteer', 'https://www.kidsclub.org/get-involved/volunteer', '2026-01-01T00:00:00Z', 'San Francisco', 'CA'),
  ('b2000000-0000-4000-8000-000000000009', 'b1000000-0000-4000-8000-000000000009', 'Tutor or Mentor with Mission Graduates', 'education', 'Volunteers provide tutoring and mentorship support to Mission District students working toward college and career goals. It is a meaningful option if you want your tutoring tied to a specific, long-term community pipeline from school through college.', array['recurring', 'counts for school hours'], 16, false, false, true, 'Varies', 'https://www.missiongraduates.org/volunteer/', 'https://www.missiongraduates.org/volunteer/', '2026-01-01T00:00:00Z', 'San Francisco', 'CA')
on conflict (id) do nothing;

