insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('b7000000-0000-4000-8000-000000000001', 'b6000000-0000-4000-8000-000000000001', 'Volunteer at Denver Animal Shelter', 'animals', 'A Junior Volunteer Program welcomes kids ages 8-15 into age-appropriate shelter roles, while general volunteers 16 and up take on the full range of shelter tasks. It is one of the few shelter programs in the region open to volunteers this young.', array['family friendly', 'recurring'], 8, false, false, true, '2-3 hrs', 'https://www.denvergov.org/Government/Agencies-Departments-Offices/Agencies-Departments-Offices-Directory/Animal-Shelter/Get-Involved/Volunteer-Animal-Shelter', 'https://www.denvergov.org/Government/Agencies-Departments-Offices/Agencies-Departments-Offices-Directory/Animal-Shelter/Get-Involved/Volunteer-Animal-Shelter', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000002', 'b6000000-0000-4000-8000-000000000002', 'Join the Humane Colorado Summer Teen Program', 'animals', '16 and 17 year-olds can join the Summer Teen Program to support Humane Colorado operations while earning service hours and real animal-welfare experience. Some assignments require volunteers to be 18, so ask about age-appropriate roles when you apply.', array['counts for school hours'], 16, false, false, true, 'Summer program', 'https://humanecolorado.org/volunteer/', 'https://humanecolorado.org/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000003', 'b6000000-0000-4000-8000-000000000003', 'Volunteer with Denver Food Rescue', 'food', 'Volunteers help recover and redistribute surplus food that would otherwise be thrown away, getting it to Denver families who need it. It is a good option if you specifically want your service to fight food waste, not just hunger.', array['recurring'], 14, false, false, true, 'Flexible', 'https://denverfoodrescue.org/volunteer/', 'https://denverfoodrescue.org/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000004', 'b6000000-0000-4000-8000-000000000004', 'Volunteer with Denver Rescue Mission', 'community', 'Volunteers help prepare and serve meals, sort donations, and support shelter operations that keep the Mission programs running. It is a well-established option if you want your service to directly support people experiencing homelessness.', array['good for crews'], 14, false, false, true, '2-3 hrs', 'https://denverrescuemission.org/volunteer/', 'https://denverrescuemission.org/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000005', 'b6000000-0000-4000-8000-000000000005', 'Volunteer at Food Bank of the Rockies', 'food', 'Volunteers 10 and up can help in the Volunteer Center inspecting and sorting donations, while those 16 and up can assist with order selection at the agency dock. Individual and group shifts run six days a week at the main distribution center.', array['good for crews', 'family friendly'], 10, false, false, true, '2-3 hrs', 'https://www.foodbankrockies.org/get-involved/volunteer/', 'https://www.foodbankrockies.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000006', 'b6000000-0000-4000-8000-000000000006', 'Volunteer with Denver Parks and Recreation', 'environment', 'Volunteers help with mulching, litter pickup, tree planting, and invasive species removal at parks and open spaces across the city. It is a flexible option that works for individuals, families, companies, or neighborhood groups alike.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.denvergov.org/Government/Agencies-Departments-Offices/Agencies-Departments-Offices-Directory/Parks-Recreation/Get-Involved-with-Denver-Parks-Recreation/Volunteer-with-Denver-Parks-Recreation', 'https://www.denvergov.org/Government/Agencies-Departments-Offices/Agencies-Departments-Offices-Directory/Parks-Recreation/Get-Involved-with-Denver-Parks-Recreation/Volunteer-with-Denver-Parks-Recreation', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000007', 'b6000000-0000-4000-8000-000000000007', 'Join a Volunteers for Outdoor Colorado Project', 'environment', 'VOC organizes trail building and stewardship projects across Colorado, connecting volunteers with hands-on outdoor work that protects public lands statewide. It is a strong pick if you want a broader range of outdoor projects than just Denver city parks.', array['outdoors', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://www.voc.org/', 'https://www.voc.org/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000008', 'b6000000-0000-4000-8000-000000000008', 'Volunteer with Denver Park Trust', 'environment', 'Volunteers support park improvement and stewardship projects that the Trust champions across Denver neighborhoods. It is a good complement to city-run park volunteering if you also want to support park advocacy and fundraising work.', array['good for crews'], 0, false, false, true, 'Varies', 'https://denverparktrust.org/get-involved/volunteer/', 'https://denverparktrust.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000009', 'b6000000-0000-4000-8000-000000000009', 'Volunteer with Special Olympics Colorado', 'sports', 'No experience is required to get started, and teens can help make posters and banners, cheer on athletes, and organize pep rallies at competitions, in addition to coaching and Unified Partner roles for older volunteers. It is a welcoming, low-barrier way to get involved with adaptive sports.', array['recurring', 'family friendly'], 13, false, false, true, 'Varies', 'https://specialolympicsco.org/getinvolved/volunteer/', 'https://specialolympicsco.org/getinvolved/volunteer/', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000010', 'b6000000-0000-4000-8000-000000000010', 'Get Involved with Denver Kids', 'community', 'Volunteers support mentoring and enrichment programs designed to help at-risk Denver Public Schools students stay engaged and on track. It is a meaningful option if you want your service focused specifically on keeping local students in school.', array['recurring'], 0, false, false, true, 'Varies', 'https://www.denverkids.org/get-involved', 'https://www.denverkids.org/get-involved', '2026-01-01T00:00:00Z', 'Denver', 'CO'),
  ('b7000000-0000-4000-8000-000000000011', 'b6000000-0000-4000-8000-000000000011', 'Join the Children''s Hospital Colorado Junior Volunteer Program', 'medicine', 'Teens 13 to 18 commit to about three hours a week for a minimum of six months, organizing events for families, doing crafts, or leading creative play with kids across hospital departments. Volunteer credit is available for scholarship applications, and the program runs both full-year and summer tracks.', array['counts for school hours', 'recurring'], 13, false, false, true, '3 hrs / week', 'https://www.childrenscolorado.org/community/support-childrens-colorado/volunteer/teen-volunteer-opportunities/', 'https://www.childrenscolorado.org/community/support-childrens-colorado/volunteer/teen-volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Denver', 'CO')
on conflict (id) do nothing;

-- Migration 021: 8 real, local Minneapolis organizations,
-- researched individually. Pure inserts with fixed ids - safe to re-run.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('b8000000-0000-4000-8000-000000000001', null, 'City of Minneapolis Animal Care and Control', 'The city-run animal shelter serving Minneapolis, caring for lost and surrendered pets with the support of community volunteers.', 'https://www.minneapolismn.gov', 'https://www.google.com/s2/favicons?domain=www.minneapolismn.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'MN', 'Minneapolis', true, true, 'ongoing', false),
  ('b8000000-0000-4000-8000-000000000002', null, 'Open Arms of Minnesota', 'A Twin Cities nonprofit preparing and delivering nutritious meals to neighbors living with serious illness.', 'https://www.openarmsmn.org', 'https://www.google.com/s2/favicons?domain=www.openarmsmn.org&sz=128', 'community', array['good for crews'], false, false, 14, 'United States', 'MN', 'Minneapolis', true, true, 'ongoing', false),
  ('b8000000-0000-4000-8000-000000000003', null, 'Second Harvest Heartland', 'The largest hunger-relief organization in Minnesota, running a major food bank operation out of Brooklyn Park that serves families across Minnesota and Wisconsin.', 'https://www.2harvest.org', 'https://www.google.com/s2/favicons?domain=www.2harvest.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 10, 'United States', 'MN', 'Minneapolis', true, true, 'both', false),
  ('b8000000-0000-4000-8000-000000000004', null, 'Minneapolis Park and Recreation Board', 'The public agency managing the Minneapolis park system, widely regarded as one of the best city park systems in the country, with volunteer programs supporting its upkeep.', 'https://www.minneapolisparks.org', 'https://www.google.com/s2/favicons?domain=www.minneapolisparks.org&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'MN', 'Minneapolis', true, true, 'both', false),
  ('b8000000-0000-4000-8000-000000000005', null, 'City of Minneapolis Clean City Program', 'The city sustainability program coordinating neighborhood cleanups and beautification projects to keep Minneapolis streets and public spaces clean.', 'http://www.minneapolismn.gov', 'https://www.google.com/s2/favicons?domain=www.minneapolismn.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'MN', 'Minneapolis', true, true, 'both', false),
  ('b8000000-0000-4000-8000-000000000006', null, 'Minnesota Department of Natural Resources', 'The state agency managing Minnesota parks, forests, and natural resources, offering volunteer opportunities across the state park and trail system.', 'https://www.dnr.state.mn.us', 'https://www.google.com/s2/favicons?domain=www.dnr.state.mn.us&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'MN', 'Minneapolis', true, true, 'both', false),
  ('b8000000-0000-4000-8000-000000000007', null, 'Special Olympics Minnesota', 'Founded in 1973, Special Olympics Minnesota serves more than 7,800 athletes with intellectual disabilities through year-round sports training and competition.', 'https://specialolympicsminnesota.org', 'https://www.google.com/s2/favicons?domain=specialolympicsminnesota.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 15, 'United States', 'MN', 'Minneapolis', true, true, 'both', false),
  ('b8000000-0000-4000-8000-000000000008', null, 'Children''s Minnesota', 'A leading pediatric hospital system in Minnesota, running a limited-enrollment High School Summer Volunteer program each year.', 'https://www.childrensmn.org', 'https://www.google.com/s2/favicons?domain=www.childrensmn.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'MN', 'Minneapolis', true, true, 'one-time', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('b9000000-0000-4000-8000-000000000001', 'b8000000-0000-4000-8000-000000000001', 'Volunteer with Minneapolis Animal Care and Control', 'animals', 'Teens 16 to 18 can volunteer with parent or guardian approval, committing to a minimum of four hours a month for six months or longer, with most individual shifts around two hours. It is a manageable, low-commitment way to build a consistent shelter volunteering record.', array['recurring'], 16, false, false, true, '2 hrs', 'https://www.minneapolismn.gov/resident-services/animals-pets/volunteer-donate/', 'https://www.minneapolismn.gov/resident-services/animals-pets/volunteer-donate/', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000002', 'b8000000-0000-4000-8000-000000000002', 'Volunteer with Open Arms of Minnesota', 'community', 'Volunteers help prepare and deliver meals to neighbors managing serious illness across the Twin Cities. It is a meaningful option if you want your service to directly support people navigating a health crisis.', array['good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.openarmsmn.org/volunteer/', 'https://www.openarmsmn.org/volunteer/', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000003', 'b8000000-0000-4000-8000-000000000003', 'Volunteer at Second Harvest Heartland', 'food', 'Individuals, groups, and youth are welcome to sign up for food sorting and packing shifts at the Brooklyn Park food bank, with skill-based volunteer projects also available. It is a good option whether you want a single shift or an ongoing group project.', array['good for crews', 'family friendly'], 10, false, false, true, '2-3 hrs', 'https://www.2harvest.org/volunteer', 'https://www.2harvest.org/volunteer', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000004', 'b8000000-0000-4000-8000-000000000004', 'Volunteer with Minneapolis Parks', 'environment', 'Volunteers support the Minneapolis park system through cleanup, planting, and stewardship projects across the city many lakes, trails, and green spaces. It is one of the easiest ways to find an outdoor project close to home in Minneapolis.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.minneapolisparks.org/volunteer-and-give/', 'https://www.minneapolisparks.org/volunteer-and-give/', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000005', 'b8000000-0000-4000-8000-000000000005', 'Volunteer with Minneapolis Clean City', 'environment', 'Volunteers take part in neighborhood cleanups and beautification projects coordinated by the city sustainability program. It is a good option if you want a quick, visible project close to home.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'http://www.minneapolismn.gov/solid-waste/cleancity/WCMSP-215835', 'http://www.minneapolismn.gov/solid-waste/cleancity/WCMSP-215835', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000006', 'b8000000-0000-4000-8000-000000000006', 'Volunteer with the Minnesota DNR', 'environment', 'Volunteers support state parks, trails, and natural resource projects across Minnesota, including many sites near the Twin Cities. It is a strong option if you want to help state land specifically rather than city parks.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.dnr.state.mn.us/volunteering/opps/index.html', 'https://www.dnr.state.mn.us/volunteering/opps/index.html', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000007', 'b8000000-0000-4000-8000-000000000007', 'Volunteer with Special Olympics Minnesota', 'sports', 'Volunteers can coach, help run the organization 92 annual competitions, support free health screenings, or assist with leadership training programs. It is a great option whatever level of commitment you are looking for, from a single event day to season-long coaching.', array['recurring', 'leadership role'], 15, false, false, true, '1-2 hrs / week', 'https://specialolympicsminnesota.org/get-involved/volunteers/', 'https://specialolympicsminnesota.org/get-involved/volunteers/', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN'),
  ('b9000000-0000-4000-8000-000000000008', 'b8000000-0000-4000-8000-000000000008', 'Join the Children''s Minnesota Teen Summer Volunteer Program', 'medicine', 'Teens 16 and 17 commit to a minimum of 30 hours over the summer, working ten three-hour weekday shifts after completing an interview, orientation, and background check. It is a serious, structured program if you are considering a pediatric healthcare career.', array['counts for school hours'], 16, false, false, true, '30 hrs total', 'https://www.childrensmn.org/support-childrens/volunteer/clinic-hospital-volunteers/teen-summer-volunteers/', 'https://www.childrensmn.org/support-childrens/volunteer/clinic-hospital-volunteers/teen-summer-volunteers/', '2026-01-01T00:00:00Z', 'Minneapolis', 'MN')
on conflict (id) do nothing;
